import type { SiteModelLaunchView, SiteModelView } from '@lodex/common';
import { findCatalogModel } from './catalogModel';
import { countStepsByType } from './siteGeneration/buildLaunchSteps';
import { readLaunchSteps } from './siteGeneration/wizardGeneration';

// The catalog model the site was generated from, or null when it was not
// generated by the wizard or the model left the catalog
const findSiteCatalogModel = async (ctx: any) => {
    const current = await ctx.siteModel.findCurrent();
    if (!current) {
        return null;
    }
    const model = findCatalogModel(
        ctx.catalogModels,
        current.modelId,
        ctx.availableLoaders,
    );
    return model ? { modelId: current.modelId as string, model } : null;
};

// What the site remembers of the wizard that generated it: cheap, it is read
// at every visit of the data add page
export const getSiteModelView = async (
    ctx: any,
): Promise<SiteModelView | null> => {
    const found = await findSiteCatalogModel(ctx);
    return found ? { modelId: found.modelId } : null;
};

// How many enrichments and precomputations a relaunch would run: costly, read
// only when the data add is confirmed
export const getSiteModelLaunchView = async (
    ctx: any,
): Promise<SiteModelLaunchView | null> => {
    const found = await findSiteCatalogModel(ctx);
    if (!found) {
        return null;
    }
    const steps = await readLaunchSteps(ctx, found.model.launchOrder);
    return countStepsByType(steps);
};
